public with sharing class AccountContactExplorerController {
    private static final Integer MAX_ACCOUNTS = 50;
    private static final Integer MAX_CONTACTS = 100;

    @AuraEnabled(cacheable=true)
    public static List<Account> getAccounts() {
        try {
            return [
                SELECT Id, Name
                FROM Account
                WITH USER_MODE
                ORDER BY Name
                LIMIT :MAX_ACCOUNTS
            ];
        } catch (Exception e) {
            throw new AuraHandledException('Unable to load accounts.');
        }
    }

    @AuraEnabled(cacheable=true)
    public static List<Contact> getContacts(Id accountId) {
        if (accountId == null) {
            return new List<Contact>();
        }

        try {
            return [
                SELECT Id, FirstName, LastName, Email, Phone
                FROM Contact
                WHERE AccountId = :accountId
                WITH USER_MODE
                ORDER BY LastName, FirstName
                LIMIT :MAX_CONTACTS
            ];
        } catch (Exception e) {
            throw new AuraHandledException('Unable to load contacts.');
        }
    }
}

@IsTest
private class AccountContactExplorerControllerTest {
    @TestSetup
    static void createRecords() {
        List<Account> accounts = new List<Account>{
            new Account(Name = 'Weyland-Yutani'),
            new Account(Name = 'Skynet')
        };
        insert accounts;

        Account skynetAccount = [
            SELECT Id
            FROM Account
            WHERE Name = 'Skynet'
            LIMIT 1
        ];
        insert new List<Contact>{
            new Contact(
                AccountId = skynetAccount.Id,
                FirstName = 'Grace',
                LastName = 'Hopper',
                Email = 'grace@example.invalid',
                Phone = '415-555-0102'
            ),
            new Contact(
                AccountId = skynetAccount.Id,
                FirstName = 'Ada',
                LastName = 'Lovelace',
                Email = 'ada@example.invalid',
                Phone = '415-555-0101'
            )
        };
    }

    @IsTest
    static void returnsOrderedAccounts() {
        Test.startTest();
        List<Account> accounts = AccountContactExplorerController.getAccounts();
        Test.stopTest();

        System.assertEquals(2, accounts.size());
        System.assertEquals('Skynet', accounts[0].Name);
        System.assertEquals('Weyland-Yutani', accounts[1].Name);
    }

    @IsTest
    static void returnsSelectedAccountContactsInNameOrder() {
        Account accountRecord = [
            SELECT Id
            FROM Account
            WHERE Name = 'Skynet'
            LIMIT 1
        ];

        Test.startTest();
        List<Contact> contacts = AccountContactExplorerController.getContacts(accountRecord.Id);
        Test.stopTest();

        System.assertEquals(2, contacts.size());
        System.assertEquals('Hopper', contacts[0].LastName);
        System.assertEquals('Lovelace', contacts[1].LastName);
    }

    @IsTest
    static void returnsEmptyListForAccountWithoutContacts() {
        Account accountRecord = [
            SELECT Id
            FROM Account
            WHERE Name = 'Weyland-Yutani'
            LIMIT 1
        ];

        Test.startTest();
        List<Contact> contacts = AccountContactExplorerController.getContacts(accountRecord.Id);
        Test.stopTest();

        System.assertEquals(0, contacts.size());
    }

    @IsTest
    static void returnsEmptyListForNullSelection() {
        Test.startTest();
        List<Contact> contacts = AccountContactExplorerController.getContacts(null);
        Test.stopTest();

        System.assertEquals(0, contacts.size());
    }
}

import { LightningElement, api } from 'lwc';
import getAccounts from '@salesforce/apex/AccountContactExplorerController.getAccounts';
import getContacts from '@salesforce/apex/AccountContactExplorerController.getContacts';

const CONTACT_COLUMNS = [
    { label: 'First Name', fieldName: 'FirstName', type: 'text' },
    { label: 'Last Name', fieldName: 'LastName', type: 'text' },
    { label: 'Email', fieldName: 'Email', type: 'text' },
    { label: 'Phone', fieldName: 'Phone', type: 'text' }
];

export default class AccountContactExplorer extends LightningElement {
    requestId = 0;
    selectedAccountId = '';
    accountOptions = [];
    contacts = [];
    isLoading = false;
    hasLoaded = false;
    hasError = false;
    errorMessage = '';
    showEmptyState = false;
    showBlankSelectionGuidance = false;

    get isLoadDisabled() {
        return this.selectedAccountId === '';
    }

    get contactColumns() {
        return CONTACT_COLUMNS;
    }

    get contactRows() {
        return this.contacts;
    }

    get contactResultsState() {
        if (this.isLoading) {
            return 'loading';
        }
        if (this.showEmptyState) {
            return 'empty';
        }
        return 'populated';
    }

    get accountOptionsWithBlank() {
        return [{ label: '-- Select an account --', value: '' }, ...this.accountOptions];
    }

    connectedCallback() {
        this.loadAccounts();
    }

    async loadAccounts() {
        try {
            const accounts = await getAccounts();
            this.accountOptions = accounts.map((account) => ({
                label: account.Name,
                value: account.Id
            }));
        } catch (error) {
            this.hasError = true;
            this.errorMessage = 'Unable to load accounts.';
        }
    }

    handleAccountChange(event) {
        this.selectedAccountId = event.detail.value;
        this.resetContactState();

        if (this.selectedAccountId === '') {
            this.showBlankSelectionGuidance = true;
        }
    }

    async handleLoadContacts() {
        if (this.selectedAccountId === '') {
            return;
        }

        const currentRequestId = ++this.requestId;
        this.isLoading = true;
        this.hasError = false;
        this.errorMessage = '';
        this.showEmptyState = false;
        this.showBlankSelectionGuidance = false;

        try {
            const contacts = await getContacts({ accountId: this.selectedAccountId });

            if (currentRequestId !== this.requestId) {
                return;
            }

            this.contacts = contacts;
            this.hasLoaded = true;
            this.showEmptyState = contacts.length === 0;
        } catch (error) {
            if (currentRequestId !== this.requestId) {
                return;
            }

            this.hasError = true;
            this.errorMessage = 'Unable to load contacts.';
        } finally {
            if (currentRequestId === this.requestId) {
                this.isLoading = false;
            }
        }
    }

    resetContactState() {
        this.requestId += 1;
        this.contacts = [];
        this.isLoading = false;
        this.hasLoaded = false;
        this.hasError = false;
        this.errorMessage = '';
        this.showEmptyState = false;
    }
}

import { describe, it, expect, jest, beforeEach } from '@jest/globals';
import { createElement } from 'lwc';
import AccountContactExplorer from 'c/accountContactExplorer';
import getAccounts from '@salesforce/apex/AccountContactExplorerController.getAccounts';
import getContacts from '@salesforce/apex/AccountContactExplorerController.getContacts';

jest.mock(
    '@salesforce/apex/AccountContactExplorerController.getAccounts',
    () => ({
        __esModule: true,
        default: jest.fn()
    }),
    { virtual: true }
);

jest.mock(
    '@salesforce/apex/AccountContactExplorerController.getContacts',
    () => ({
        __esModule: true,
        default: jest.fn()
    }),
    { virtual: true }
);

const SYNTHETIC_ACCOUNTS = [
    { Id: '001000000000001', Name: 'Skynet' },
    { Id: '001000000000002', Name: 'Weyland-Yutani' }
];

const SYNTHETIC_CONTACTS = [
    {
        Id: '003000000000001',
        FirstName: 'Grace',
        LastName: 'Hopper',
        Email: 'grace@example.invalid',
        Phone: '415-555-0102'
    },
    {
        Id: '003000000000002',
        FirstName: 'Ada',
        LastName: 'Lovelace',
        Email: 'ada@example.invalid',
        Phone: '415-555-0101'
    }
];

function createComponent() {
    const element = createElement('c-account-contact-explorer', {
        is: AccountContactExplorer
    });
    document.body.appendChild(element);
    return element;
}

function tick() {
    return new Promise((resolve) => setTimeout(resolve, 0));
}

describe('c-account-contact-explorer', () => {
    beforeEach(() => {
        jest.clearAllMocks();
        getAccounts.mockResolvedValue(SYNTHETIC_ACCOUNTS);
        getContacts.mockResolvedValue(SYNTHETIC_CONTACTS);
    });

    it('renders account options including blank selection', async () => {
        const element = createComponent();
        await tick();

        const combobox = element.shadowRoot.querySelector('[data-role="account-selector"]');
        expect(combobox).not.toBeNull();
        expect(combobox.options.length).toBe(3);
        expect(combobox.options[0].value).toBe('');
        expect(combobox.options[0].label).toBe('-- Select an account --');
        expect(combobox.options[1].value).toBe('001000000000001');
        expect(combobox.options[1].label).toBe('Skynet');
    });

    it('disables Load button for blank selection', async () => {
        const element = createComponent();
        await tick();

        const button = element.shadowRoot.querySelector('[data-role="load-contacts"]');
        expect(button.disabled).toBe(true);
    });

    it('enables Load button for valid selection', async () => {
        const element = createComponent();
        await tick();

        const combobox = element.shadowRoot.querySelector('[data-role="account-selector"]');
        combobox.value = '001000000000001';
        combobox.dispatchEvent(new CustomEvent('change', { detail: { value: '001000000000001' } }));
        await tick();

        const button = element.shadowRoot.querySelector('[data-role="load-contacts"]');
        expect(button.disabled).toBe(false);
    });

    it('loads contacts on explicit action', async () => {
        const element = createComponent();
        await tick();

        const combobox = element.shadowRoot.querySelector('[data-role="account-selector"]');
        combobox.value = '001000000000001';
        combobox.dispatchEvent(new CustomEvent('change', { detail: { value: '001000000000001' } }));
        await tick();

        const button = element.shadowRoot.querySelector('[data-role="load-contacts"]');
        button.click();
        await tick();

        const datatable = element.shadowRoot.querySelector('[data-role="contact-results"]');
        expect(datatable).not.toBeNull();
        expect(datatable.data.length).toBe(2);
        expect(datatable.data[0].FirstName).toBe('Grace');
        expect(datatable.data[1].LastName).toBe('Lovelace');
    });

    it('shows loading state during request', async () => {
        const element = createComponent();
        await tick();

        const combobox = element.shadowRoot.querySelector('[data-role="account-selector"]');
        combobox.value = '001000000000001';
        combobox.dispatchEvent(new CustomEvent('change', { detail: { value: '001000000000001' } }));
        await tick();

        let resolvePromise;
        getContacts.mockImplementationOnce(() => {
            return new Promise((resolve) => {
                resolvePromise = resolve;
            });
        });

        const button = element.shadowRoot.querySelector('[data-role="load-contacts"]');
        button.click();
        await tick();

        const loadingIndicator = element.shadowRoot.querySelector('[data-state="loading"]');
        expect(loadingIndicator).not.toBeNull();

        resolvePromise(SYNTHETIC_CONTACTS);
        await tick();

        const datatable = element.shadowRoot.querySelector('[data-role="contact-results"]');
        expect(datatable).not.toBeNull();
    });

    it('shows empty state for account without contacts', async () => {
        getContacts.mockResolvedValueOnce([]);

        const element = createComponent();
        await tick();

        const combobox = element.shadowRoot.querySelector('[data-role="account-selector"]');
        combobox.value = '001000000000002';
        combobox.dispatchEvent(new CustomEvent('change', { detail: { value: '001000000000002' } }));
        await tick();

        const button = element.shadowRoot.querySelector('[data-role="load-contacts"]');
        button.click();
        await tick();

        const emptyIndicator = element.shadowRoot.querySelector('[data-state="empty"]');
        expect(emptyIndicator).not.toBeNull();
        const datatable = element.shadowRoot.querySelector('[data-role="contact-results"]');
        expect(datatable).toBeNull();
    });

    it('shows safe error for contact load failure', async () => {
        getContacts.mockRejectedValueOnce(new Error('Internal error'));

        const element = createComponent();
        await tick();

        const combobox = element.shadowRoot.querySelector('[data-role="account-selector"]');
        combobox.value = '001000000000001';
        combobox.dispatchEvent(new CustomEvent('change', { detail: { value: '001000000000001' } }));
        await tick();

        const button = element.shadowRoot.querySelector('[data-role="load-contacts"]');
        button.click();
        await tick();

        const alert = element.shadowRoot.querySelector('[role="alert"]');
        expect(alert).not.toBeNull();
        expect(alert.textContent).toContain('Unable to load contacts.');
        const datatable = element.shadowRoot.querySelector('[data-role="contact-results"]');
        expect(datatable).toBeNull();
    });

    it('shows safe error for account load failure', async () => {
        getAccounts.mockRejectedValueOnce(new Error('Internal error'));

        const element = createComponent();
        await tick();

        const alert = element.shadowRoot.querySelector('[role="alert"]');
        expect(alert).not.toBeNull();
        expect(alert.textContent).toContain('Unable to load accounts.');
    });

    it('prevents stale response from overwriting current state', async () => {
        const element = createComponent();
        await tick();

        const combobox = element.shadowRoot.querySelector('[data-role="account-selector"]');
        combobox.value = '001000000000001';
        combobox.dispatchEvent(new CustomEvent('change', { detail: { value: '001000000000001' } }));
        await tick();

        let resolveFirst;
        getContacts.mockImplementationOnce(() => {
            return new Promise((resolve) => {
                resolveFirst = resolve;
            });
        });

        const button = element.shadowRoot.querySelector('[data-role="load-contacts"]');
        button.click();
        await tick();

        combobox.value = '001000000000002';
        combobox.dispatchEvent(new CustomEvent('change', { detail: { value: '001000000000002' } }));
        await tick();

        resolveFirst(SYNTHETIC_CONTACTS);
        await tick();

        const datatable = element.shadowRoot.querySelector('[data-role="contact-results"]');
        expect(datatable).toBeNull();
    });

    it('shows blank selection guidance when selection is cleared', async () => {
        const element = createComponent();
        await tick();

        const combobox = element.shadowRoot.querySelector('[data-role="account-selector"]');
        combobox.value = '001000000000001';
        combobox.dispatchEvent(new CustomEvent('change', { detail: { value: '001000000000001' } }));
        await tick();

        const button = element.shadowRoot.querySelector('[data-role="load-contacts"]');
        button.click();
        await tick();

        const datatable = element.shadowRoot.querySelector('[data-role="contact-results"]');
        expect(datatable).not.toBeNull();

        combobox.value = '';
        combobox.dispatchEvent(new CustomEvent('change', { detail: { value: '' } }));
        await tick();

        const alert = element.shadowRoot.querySelector('[role="alert"]');
        expect(alert).not.toBeNull();
        expect(alert.textContent).toContain('Select an account before loading contacts.');
        const newDatatable = element.shadowRoot.querySelector('[data-role="contact-results"]');
        expect(newDatatable).toBeNull();
        const newButton = element.shadowRoot.querySelector('[data-role="load-contacts"]');
        expect(newButton.disabled).toBe(true);
    });
});
